<section class="sc-detail" aria-live="polite" aria-atomic="false">
    @if($selected)
        @php ['need' => $need, 'booking' => $booking, 'offer' => $offer, 'state' => $state, 'paymentLabel' => $paymentLabel, 'expiredOffer' => $expiredOffer, 'person' => $person] = $selected; @endphp
        <div class="sc-detail-top"><p class="sc-eyebrow">{{ $need->starts_at->isToday() ? 'Today’s visit' : 'Visit details' }}</p><span class="sc-badge sc-badge-{{ $selected['tone'] }}">{{ $state }}</span></div>
        <h2>{{ $need->starts_at->copy()->setTimezone($care->timezone)->format('l, M j') }}</h2>
        <p class="sc-detail-time"><x-shared-care-icon name="clock" />{{ $need->starts_at->copy()->setTimezone($care->timezone)->format('g:i A') }}–{{ $need->ends_at->copy()->setTimezone($care->timezone)->format('g:i A') }}<span>{{ $need->kind === 'extra' ? 'Extra visit' : '' }}</span></p>
        @if($person)<div class="sc-detail-person"><x-caregiver-identity :caregiver="$person" :label="$state === 'Waiting for reply' ? 'Waiting for a reply from' : 'Caregiver'" /></div>@else<div class="sc-open-visit"><span><x-shared-care-icon name="{{ $need->status === 'waived' ? 'calendar' : 'people' }}" /></span><h3>{{ $need->status === 'waived' ? 'A day without care' : 'Let’s find the right person' }}</h3><p>{{ $need->status === 'waived' ? 'You marked these hours as no longer needed.' : 'These hours are still on your schedule. No caregiver is booked yet.' }}</p></div>@endif
        @if($state === 'Check arrival')<p class="sc-detail-warning">No check-in has been recorded. Contact your caregiver or open the visit for no-show and support options.</p>@elseif($state === 'Planned')<p class="sc-detail-note">{{ $person?->name }} is assigned. The dated booking will be created closer to this date.</p>@elseif($state === 'Visit setup needs attention')<p class="sc-detail-warning">A caregiver is assigned, but the booking needs attention. Contact support before arranging overlapping care.</p>@elseif($state === 'Waiting for reply')<p class="sc-detail-note">The caregiver still needs to accept. This visit is not booked yet.</p>@elseif($state === 'Missed care')<p class="sc-detail-warning">These hours have passed without a booked visit. Get help to review what happened.</p>@endif
        @if($booking)
            <div class="sc-detail-meta"><span><x-shared-care-icon name="pin" />{{ $care->sourceRequest->city ?: 'Care location' }}{{ $care->sourceRequest->state ? ', '.$care->sourceRequest->state : '' }}</span><span><x-shared-care-icon name="receipt" />{{ $paymentLabel }}</span></div>
            <a href="{{ route('family.requests.show', ['careRequest' => $booking->care_request_id, 'tab' => in_array($state, ['Check arrival', 'Under review']) ? 'support' : 'shift']) }}" wire:navigate class="sc-button sc-button-primary sc-button-full">{{ $paymentLabel === 'Payment action needed' ? 'Review payment' : ($state === 'Check arrival' ? 'Get help with this visit' : 'Open visit') }}<x-shared-care-icon name="arrow" /></a>
            @if($need->starts_at->isFuture() && $need->status === 'needed')<details class="sc-visit-options"><summary>Change this visit</summary><button type="button" wire:click="openCancel({{ $need->id }}, true)">I need a different caregiver</button><button type="button" wire:click="openCancel({{ $need->id }}, false)">I don’t need this visit</button></details>@else<a class="sc-detail-help" href="{{ route('family.requests.show', ['careRequest' => $booking->care_request_id, 'tab' => 'support']) }}" wire:navigate>Questions or changes? Get help</a>@endif
        @elseif($need->starts_at->isFuture() && $need->status === 'needed' && !in_array($state, ['Planned', 'Visit setup needs attention']))
            @if($offer && !$expiredOffer)<button type="button" wire:click="withdrawOffer({{ $need->id }})" wire:loading.attr="disabled" class="sc-button sc-button-full">Withdraw request</button>@else<button type="button" wire:click="openExtra({{ $need->id }})" class="sc-button sc-button-primary sc-button-full">Ask my care team <x-shared-care-icon name="arrow" /></button><a href="{{ $applicantsUrl }}" wire:navigate class="sc-detail-help">Find another caregiver</a>@endif
            <button type="button" wire:click="openCancel({{ $need->id }}, false)" class="sc-detail-help">I don’t need these hours</button>
        @elseif($need->starts_at->isFuture() && $need->status === 'waived')<button type="button" wire:click="restoreNeed({{ $need->id }})" class="sc-button sc-button-full">I need care again</button>
        @else<a href="{{ route('support.index') }}" wire:navigate class="sc-button sc-button-full">Get help <x-shared-care-icon name="arrow" /></a>@endif
    @else
        <div class="sc-empty"><x-shared-care-icon name="calendar" /><h2>A little breathing room</h2><p>No care is requested for this week.</p><button type="button" wire:click="openExtra" class="sc-button">Add a visit</button></div>
    @endif
</section>
